import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            if (n > m) {
                int t = n;
                n = m;
                m = t;
            }
            long V = (long) n * m;

            if (V < 100) {
                int v = (int) V;
                List<Integer>[] g = new List[v];
                for (int i = 0; i < v; i++) {
                    g[i] = new ArrayList<>();
                }
                for (int i = 0; i < v; i++) {
                    int r1 = i / m;
                    int c1 = i % m;
                    if ((r1 + c1) % 2 == 0) {
                        for (int j = 0; j < v; j++) {
                            int r2 = j / m;
                            int c2 = j % m;
                            if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 3) {
                                g[i].add(j);
                            }
                        }
                    }
                }
                int pairs = maxMatching(g, m);
                out.println(pairs * 2);
            } else {
                long res;
                if (n == 1) {
                    res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
                } else {
                    res = V;
                    res -= res % 2;
                }
                out.println(res);
            }
        }

        static int maxMatching(List<Integer>[] g, int cols) {
            int v = g.length;
            int[] matchR = new int[v];
            Arrays.fill(matchR, -1);
            int pairs = 0;
            for (int u = 0; u < v; u++) {
                int r = u / cols;
                int c = u % cols;
                if ((r + c) % 2 == 0) {
                    boolean[] seen = new boolean[v];
                    if (dfs(u, g, matchR, seen)) {
                        pairs++;
                    }
                }
            }
            return pairs;
        }

        static boolean dfs(int u, List<Integer>[] g, int[] matchR, boolean[] seen) {
            for (int v : g[u]) {
                if (seen[v]) continue;
                seen[v] = true;
                if (matchR[v] == -1 || dfs(matchR[v], g, matchR, seen)) {
                    matchR[v] = u;
                    return true;
                }
            }
            return false;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1) throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
